INSERT INTO purpose VALUES('core-term','syntax::equal_certificate_folded','function','Compares native certificate syntax as equal_certificate_syntax does, reading a returned composite as its fold, so a rewrite between p then q and its transport keeps its meaning.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('core-term','syntax::equal_certificate_syntax','function','Compares native certificate syntax, erasing evidence but performing no reduction, so distinct translator programs stay distinct even if extensionally equal.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('core-term','syntax::equal_comp_type_folded','function','Compares computation type syntax as equal_comp_type_syntax does, reading a returned composite as its fold.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('core-term','syntax::equal_comp_type_syntax','function','Compares computation type syntax as equal_type_syntax compares value types, so separately allocated equal codata types compare equal.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('core-term','syntax::equal_computation_syntax_up_to_free','function','Compares two computations as syntax up to what each reads free, so a lambda written twice over scopes laid out apart agrees, each variable it reads free paired by place.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('core-term','syntax::equal_shared_certificate_syntax','function','Compares native certificate syntax as equal_certificate_syntax does, reading the two sides as the graphs they are shared as, in time linear in the nodes they reach.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('core-term','syntax::equal_type_folded','function','Compares value type syntax as equal_type_syntax does, reading a returned composite as its fold.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('core-term','syntax::equal_type_reading','function','Compares type syntax as a printed type reads, so the types every checker reads alike compare equal.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('core-term','syntax::equal_type_syntax','function','Compares signature type syntax without making allocation identity observable, so separately allocated equal signatures compare equal.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('core-term','syntax::folded_computation','function','The fold a returned composite realises, as the bridge erases it, so every reader that compares terms reads the composite as the kernel replays it.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('core-term','syntax::identified_words','function','The type of words the path type Path[.A = carrier](left, right) reads as: the declaration whose free cells loop at a point both endpoints spell.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('core-term','syntax::unstaged','function','The base of a staged value type, or any other type as it is.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('core-term','syntax::unworded','module','Names the reason [`super::identified_words`] answered no declaration.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('core-term','tactic::Tactic','struct','The tactic a splice runs at its goal: a count of introductions, then an assumption.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('core-term','tactic::TooManyIntros','struct','A count of introductions at or past the limit, which no tactic makes.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('core-term','ua::Description','struct','A description as a stratum reads it: its name and its generators, in written order.',NULL,'fits','sound',NULL);
